mapper.select:
select * from student_score where student_info_id = #{studentInfoId}
and course_name like concat('%', #{courseName},'%')
and school_year = #{startYear} and term = '春'
and school_year = #{startYear} and term = '秋'
and ( (school_year = #{startYear} and term = '秋') or (school_year = #{endYear} and term = '春') )
and term = #{term}

select *
from student_score
where student_info_id = #{studentInfoId}
  and school_year = #{schoolYear}
  and term = #{term}
order by id asc
